// A host runs what it generated by the id the engine froze it under (<case>@<digest16>), and it learns that id from
// what the engine shows it -- context's `versions`, each with the obligation its design was for -- never from the
// journal, which a host in a benchmark's runner (or anywhere a relay stands between them) cannot read.
import assert from "node:assert/strict";
import { test } from "node:test";
import { judgeDecision } from "../src/investigation/decision.mjs";
import { contextFor, loopWorld } from "../src/investigation/index.mjs";
import { resultView } from "../src/investigation/loop.mjs";
import { eventIdOf } from "../src/investigation/store.mjs";
import { started } from "./autonomous-qa.harness.mjs";

const VERSION = `gen-billing-once@${"a1".repeat(8)}`;

test("context names every frozen version by the id run-version takes, and the obligation it was designed for", () => {
  const t = started();
  assert.deepEqual(contextFor(t.w).versions, [], "nothing generated, nothing named");
  t.w.store.appendOnce(t.id, "designed", { id: "dsg-1", eventId: eventIdOf("designed", "tob-abc", 0, "d1"), obligation: "tob-abc", design: "tds-1", digest: "d1", state: "designed" });
  t.w.store.appendOnce(t.id, "version", { id: "ver-1", eventId: eventIdOf("version", "tds-1", 0, "c1"), design: "tds-1", case: "gen-billing-once", version: VERSION, digest: "c1" });
  const [v] = contextFor(t.w).versions;
  assert.deepEqual(v, { id: "ver-1", version: VERSION, obligation: "tob-abc", design: "tds-1", case: "gen-billing-once" });
  assert.match(v.version, /^[A-Za-z0-9][A-Za-z0-9._-]{0,120}@[0-9a-f]{16}$/, "the very form run-version's check accepts");
});

test("a design and a version are records a decision may cite, as the step that made them named them", () => {
  const t = started();
  t.w.store.appendOnce(t.id, "designed", { id: "dsg-1", eventId: eventIdOf("designed", "tob-abc", 0, "d1"), obligation: "tob-abc", design: "tds-1", digest: "d1", state: "designed" });
  t.w.store.appendOnce(t.id, "version", { id: "ver-1", eventId: eventIdOf("version", "tds-1", 0, "c1"), design: "tds-1", case: "gen-billing-once", version: VERSION, digest: "c1" });
  const lw = loopWorld(t.w);
  const raw = { schemaVersion: 1, decisionId: "d-refs", expectedRevision: lw.model.position, target: lw.frontier[0]?.id, action: { kind: "run-version", version: VERSION }, evidenceRefs: ["ver-1", "dsg-1"], reason: "run what was frozen" };
  const said = (() => { try { judgeDecision(raw, lw); return ""; } catch (e) { return e.message; } })();
  assert.doesNotMatch(said, /^REFS:/, said);
  const unknown = (() => { try { judgeDecision({ ...raw, decisionId: "d-refs-2", evidenceRefs: ["ver-9"] }, lw); return ""; } catch (e) { return e.message; } })();
  assert.match(unknown, /^REFS: evidenceRefs ver-9 name no record/, "an id nothing recorded is still refused");
});

test("a step's answer says what its action came to: the owner's word, its stage or rule and why -- never the values", () => {
  assert.equal(resultView(undefined), null);
  const blocked = resultView({ outcome: "ENVIRONMENT_BLOCKED", why: "schedule billing-daily: this sandbox minted no hooks token" });
  assert.deepEqual([blocked.outcome, blocked.why], ["ENVIRONMENT_BLOCKED", "schedule billing-daily: this sandbox minted no hooks token"]);
  const failed = resultView({ outcome: "GENERATION_FAILED", stage: "validate", findings: [{ rule: "UNKNOWN_FIELD", say: "step 2 has a field nobody declared" }] });
  assert.deepEqual([failed.outcome, failed.stage, failed.findings], ["GENERATION_FAILED", "validate", ["UNKNOWN_FIELD: step 2 has a field nobody declared"]]);
  const made = resultView({ outcome: "DRAFT_CREATED", version: VERSION, design: "tds-1", case: "gen-billing-once", digests: { case: "x" } });
  assert.deepEqual(Object.keys(made).sort(), ["execution", "findings", "outcome", "rule", "stage", "stopped", "version", "why"], "an allow-list: nothing else of the result reaches the host");
  assert.equal(made.version, VERSION);
});

test("a run that stopped short says where, and what its stop said -- five fields by allow-list, scrubbed and bounded at the door", () => {
  const says = "postgres.reference read: a read below the interface names what it reads: request.key (the bound key column's value) or request.match, 4 columns at most — never a whole table";
  const refused = resultView({ outcome: "INVALID_TEST", rule: "TEST_WRONG", why: "the test itself was refused before it could rule on anything", stopped: { step: 6, do: "call", capability: "orbit.state.read", as: "refused", says, request: { businessKey: "k" }, observed: { count: 0 } } });
  assert.deepEqual(refused.stopped, { step: 6, do: "call", capability: "orbit.state.read", as: "refused", says });
  const long = resultView({ outcome: "ENVIRONMENT_BLOCKED", stopped: { step: "2", as: "blocked", says: `token: abcdefghijklmnop ${"x".repeat(900)}` } });
  assert.deepEqual([long.stopped.step, long.stopped.do, long.stopped.says.length], [null, null, 600]);
  assert.match(long.stopped.says, /^token \[redacted\]/);
  assert.equal(resultView({ outcome: "SATISFIED" }).stopped, null, "a run that held stopped nowhere");
  assert.deepEqual(resultView({ outcome: "CONTRADICTED", stopped: { step: 3, do: "call", capability: "orbit.worker.observe", as: "failed", says: null } }).stopped, { step: 3, do: "call", capability: "orbit.worker.observe", as: "failed", says: null }, "a failure is named and says nothing");
});

// What a real Claude Code QA row taught (0.4.0, ORBIT-QA-001 on Opus): a failed observation whose match left out the
// redelivery of its own message was a false alarm nobody could see through. What the stopped step's match left out
// reaches the host -- by allow-list at this door again: names for fields, a scalar or a short text for each value, the
// newest three, every word scrubbed and bounded -- and only when there is something.
test("what the stopped step's own match left out reaches the host by allow-list, scrubbed and bounded -- and only when it left something out", () => {
  const excluded = { field: "attempts", count: 5, by: ["outcome", "not a name!"], subject: ["messageId"], items: [{ messageId: "m-0" }, { messageId: "m-1", outcome: "fault", deliveryAttempt: 1, "bad key": "x", nested: { token: "abcdefghijklmnop" } }, { messageId: "m-1", outcome: "duplicate", deliveryAttempt: 2, terminalReason: null }, { messageId: "m-1", outcome: `${"y".repeat(300)}` }], say: `5 of the attempts … authorization: Bearer abc.def.ghi ${"z".repeat(900)}`, extra: "dropped" };
  const out = resultView({ outcome: "CONTRADICTED", stopped: { step: 5, do: "call", capability: "orbit.worker.observe", as: "failed", says: null, excluded } }).stopped;
  assert.deepEqual(Object.keys(out.excluded), ["field", "count", "by", "items", "say"], "the five it carries, and nothing else");
  assert.deepEqual([out.excluded.field, out.excluded.count, out.excluded.by], ["attempts", 5, ["outcome"]]);
  assert.deepEqual(out.excluded.items.map((i) => i.messageId), ["m-1", "m-1", "m-1"], "the newest three");
  assert.deepEqual(out.excluded.items[0], { messageId: "m-1", outcome: "fault", deliveryAttempt: 1, nested: '{"token [redacted]}' }, "a field that is not a name is dropped; a value that is not a scalar is a short scrubbed text");
  assert.equal(out.excluded.items[1].terminalReason, null);
  assert.equal(out.excluded.items[2].outcome.length, 120, "bounded");
  assert.equal(out.excluded.say.length, 600, "bounded");
  assert.equal(out.excluded.say.includes("abc.def.ghi"), false, out.excluded.say);
  assert.equal("excluded" in resultView({ outcome: "CONTRADICTED", stopped: { step: 5, as: "failed", says: null } }).stopped, false, "nothing left out, nothing said");
  assert.equal("excluded" in resultView({ outcome: "CONTRADICTED", stopped: { step: 5, as: "failed", excluded: { count: 0, items: [] } } }).stopped, false);
});

// What a real Claude Code QA row taught (0.4.0, ORBIT-QA-006 on Opus): a test of one investigation made the schedule reach a
// period whose business key an earlier test of the same investigation had used, and the duplicate the clean application
// settled it as read as a defect. What a design names that an earlier version named too reaches the host beside the
// answer -- by allow-list at this door again: the version, its obligation and shape, each value and the words it was named
// under, the sentence; every word scrubbed and bounded, the newest four -- and only when there is something.
test("what a frozen design shares with an earlier version reaches the host by allow-list, scrubbed and bounded -- and only when it shares something", () => {
  const line = (n, over = {}) => ({ version: `gen-${n}@${"b2".repeat(8)}`, obligation: `tob-${n}`, shape: "effect-once-per-key", keys: [{ value: "tenant-a|inv-a|period", as: ["correlationId", "not a word!"], extra: 1 }], say: "correlationId tenant-a|inv-a|period — named by …", design: { skeleton: {} }, ...over });
  const made = resultView({ outcome: "DRAFT_CREATED", version: VERSION, shared: [line(1), line(2), line(3), line(4), line(5, { keys: [1, 2, 3, 4, 5].map((k) => ({ value: `a@b.test ${k} ${"k".repeat(200)}`, as: ["businessKey"] })), say: "z".repeat(900) })] });
  assert.equal(made.outcome, "DRAFT_CREATED", "the outcome is the one it earned");
  assert.deepEqual(made.shared.map((s) => s.obligation), ["tob-2", "tob-3", "tob-4", "tob-5"], "the newest four");
  assert.deepEqual(made.shared[0], { version: `gen-2@${"b2".repeat(8)}`, obligation: "tob-2", shape: "effect-once-per-key", keys: [{ value: "tenant-a|inv-a|period", as: ["correlationId"] }], say: "correlationId tenant-a|inv-a|period — named by …" }, "what it carries and nothing else: never the earlier design");
  assert.deepEqual([made.shared[3].keys.length, made.shared[3].keys[0].value.length, made.shared[3].say.length], [4, 120, 600], "bounded");
  assert.match(made.shared[3].keys[0].value, /^\[upn\] 1 /, "scrubbed by shape");
  assert.equal("shared" in resultView({ outcome: "DRAFT_CREATED", version: VERSION, shared: [] }), false, "nothing shared, nothing said");
  assert.deepEqual(resultView({ outcome: "DRAFT_CREATED", shared: [{ version: 7, keys: "x" }] }).shared, [{ version: null, obligation: null, shape: null, keys: [], say: null }], "a field of another kind is null, never echoed");
  const stated = resultView({ outcome: "DRAFT_CREATED", shared: [{ criterion: `SLA-1/E1 ${"z".repeat(200)}`, shape: "completes-by-deadline", keys: [{ value: "k-1", as: ["correlationId"] }], say: "correlationId k-1 — an accepted criterion …", design: { secret: true } }] }).shared[0];
  assert.deepEqual(stated, { version: null, obligation: null, shape: "completes-by-deadline", criterion: `SLA-1/E1 ${"z".repeat(71)}`, keys: [{ value: "k-1", as: ["correlationId"] }], say: "correlationId k-1 — an accepted criterion …" }, "a key a criterion states for another shape says which criterion, bounded, and nothing else");
});

test("context lists the names a design's refs may take here, from the generation port -- and nothing when none is bound", () => {
  const t = started();
  assert.equal(contextFor(t.w).bindings, null, "no generation port, no list");
  const listed = { endpoint: [{ alias: "invoice-read", of: "invoice-app", path: "/api", says: "reads one invoice" }], workload: [{ alias: "worker", of: "invoice-app", says: "" }] };
  assert.deepEqual(contextFor({ ...t.w, generation: { bindable: () => listed } }).bindings, listed);
  assert.equal(contextFor({ ...t.w, generation: { bindable: () => { throw new Error("graph unreadable"); } } }).bindings, null, "a graph that cannot be read lists nothing, never fails the context");
});
